export type DrillArea =
  | "claim-warrant-impact"
  | "rebuttal"
  | "evidence-evaluation"
  | "weighing"
  | "clash"
  | "signposting"
  | "constructive-speech";

export const DRILL_AREAS: Array<{ id: DrillArea; label: string; skillSlug: string; description: string }> = [
  { id: "claim-warrant-impact", label: "Claim / Warrant / Impact", skillSlug: "debate-claim-building", description: "Build a complete argument: claim, the reasoning that proves it, and why it matters." },
  { id: "rebuttal", label: "Rebuttal", skillSlug: "debate-rebuttal", description: "Answer an opposing argument directly and strategically." },
  { id: "evidence-evaluation", label: "Evidence evaluation", skillSlug: "debate-evidence", description: "Judge which evidence actually supports a claim and how strong it is." },
  { id: "weighing", label: "Weighing", skillSlug: "debate-weighing", description: "Compare impacts and explain which should decide the round." },
  { id: "clash", label: "Clash", skillSlug: "debate-clash", description: "Find the real point of disagreement and pick the response that actually engages it." },
  // The skill slugs below deliberately do NOT match their lesson ids (`debate-signposting`,
  // `debate-constructive-speeches`). A slug equal to a lesson id resolves as `canonical-redirect`
  // in `resolveSkillsSlug`, so evidence written under it could never be reached as a skill.
  { id: "signposting", label: "Signposting", skillSlug: "debate-flow-signposting", description: "Tell the judge where each answer belongs so it lands on the argument it answers." },
  { id: "constructive-speech", label: "Constructive speech", skillSlug: "debate-case-construction", description: "Compose a whole constructive: order the contentions, develop each one, build your own case." }
];

export const DRILL_SKILL_SLUGS = DRILL_AREAS.map((a) => a.skillSlug);

/**
 * M15 Learning Architecture Slice 1 — the single source of truth for "is this string a real Debate
 * drill area?".
 *
 * The deep link `/study-arcade?track=debate&area=rebuttal` carries UNTRUSTED URL text, so it is
 * narrowed here against `DRILL_AREAS` rather than cast. An unknown, empty or cross-track value is
 * not an error — it simply is not an area, and the caller keeps today's "mixed" default. Nothing
 * downstream of this guard can receive a value the drill bank does not have.
 */
export function isDrillArea(value: unknown): value is DrillArea {
  return typeof value === "string" && DRILL_AREAS.some((a) => a.id === value);
}

/** Narrow an untrusted query value to a real area, or `undefined` when it is not one. */
export function drillAreaFromQuery(value: unknown): DrillArea | undefined {
  return isDrillArea(value) ? value : undefined;
}

/**
 * The learner-facing name of an area, read from `DRILL_AREAS` so a CTA that names a drill cannot
 * drift from the drill it links to. `DrillArea` is a closed union, so every input has a label.
 */
export function drillAreaLabel(area: DrillArea): string {
  return DRILL_AREAS.find((a) => a.id === area)!.label;
}

export type DrillQuestion = {
  id: string;
  area: DrillArea;
  question: string;
  choices: string[];
  correctAnswer: string;
  explanation: string;
};

