/**
 * Skills whose DURABLE MASTERY WRITES are suspended while their evidence model is revalidated.
 *
 * Withholding the unfair items is not sufficient on its own. The eight rebuttal items that remain
 * servable carry roughly five distinct judgements between them — rb-02/rb-16 are one, rb-13/rb-17
 * are one, rb-14/rb-15 are a measurement-dependent pair — while the legacy model counts five
 * distinct QUESTION IDS as five independent measurements. That is precisely the assumption the
 * Constructive secure-evidence work exists to reject, so the remaining items are practice and the
 * mastery claim pauses rather than being re-earned on a smaller version of the same mistake.
 *
 * Held is not deleted and not disabled: the Skill row stays, existing records are untouched, and
 * practice still serves and still grades. What stops is new durable evidence — no MasteryProgress
 * advance and no new review scheduling from a submission in a held skill.
 *
 * Lifting this requires the rebuttal evidence model to be revalidated, not merely a bigger bank.
 */
export const DEBATE_MASTERY_HELD_SKILLS: ReadonlyArray<string> = ["debate-rebuttal"];

/** Is durable mastery writing suspended for `skillSlug`? Pure; safe to call from any layer. */
export function debateMasteryHeld(skillSlug: string | null | undefined): boolean {
  return Boolean(skillSlug) && DEBATE_MASTERY_HELD_SKILLS.includes(skillSlug as string);
}

// ELIGIBILITY IS NOT SESSION CAPACITY — read this before "fixing" any 29 back to a 30.
//
// Two different true numbers describe the rebuttal area after the B2.2 release, and collapsing them
// into one is the mistake this note exists to prevent:
//
//   GLOBAL INDIVIDUAL ELIGIBILITY — 30 of 30 rebuttal items may serve. Nothing is withheld; every
//   item, including both rb-14 and rb-15, is a live evidence-eligible unit.
//
//   MAXIMUM DISTINCT IN ONE VALID SESSION — 29. rb-14 and rb-15 may never co-serve, so exactly one
//   of them appears in any single fresh session.
//
//   THE SAME ARITHMETIC AT BANK SCALE, stated structurally rather than as a snapshot: the maximum
//   distinct Debate ids in one clean-history full-bank session is the eligible authored pool
//   (DRILL_BANK minus DEBATE_DRILL_HELD_IDS) minus one member for each entry of
//   DEBATE_DRILL_EXCLUSIVE_GROUPS whose members are all eligible. Both terms move as the bank and
//   the group registry grow, so do NOT record either as a fixed number here — collapsing this into
//   a remembered total is exactly what went stale when the Signposting area and the sp-26/sp-27
//   group landed. HISTORICAL, SCOPED: at the B2.3 wg-08 release the bank held 150 items and one
//   group, giving 149 of 150, up from 148 and never 150.
//
// A learner's own fresh-session pool can be smaller still: retained-exposure exclusion removes a
// sibling the learner has already been ISSUED, and removes both once both have been seen. That is
// the measurement-validity rule working, never under-serving and never a builder bug.

// Draw a session of `count` original questions. If `areas` is given, restrict to them (focused drill).
// MEASUREMENT-DEPENDENT PAIRS (owner ruling, 2026-08-25). Two bank items are measurement-dependent
// when exposure to one materially discloses the answer logic the other exists to measure. rb-14 and
// rb-15 are such a pair: rb-14's keyed contrast states, in the same scenario terms, the two component
// claims whose composition is rb-15's key, and rb-15's clause-ordered choices positionally label the
// exact binding rb-14 tests. Disclosure runs through BOTH the post-answer explanation AND the rendered
// choice text alone, so neither delayed feedback nor a fixed serve order fixes it — only not putting
// them in front of the same learner close together.
//
// The adjudication that this pair REQUIRES a control lives outside this file, in
// scripts/debate-pair-adjudications.json, deliberately: a runtime constant must never be the sole
// record of its own necessity. The smoke suite compares that checked-in record (EXPECTED) against
// this constant (ACTUAL), so deleting the group here fails rather than silently disabling the control.
export const DEBATE_DRILL_EXCLUSIVE_GROUPS: ReadonlyArray<ReadonlyArray<string>> = [
  ["rb-14", "rb-15"],
  // sp-26/sp-27 MEASUREMENT DEPENDENCY (post-30 hostile audit). Not a wording collision: the pair was
  // separated semantically, given different task forms, stripped of lexical overlap, and sp-27 was
  // rebuilt as a balanced 2x2 with the return-to-own-case transition held constant and correct across
  // all four options. Adversarial serve-order review still found sp-27 -> sp-26 MATERIAL: sp-27's stem
  // certifies that constant as correct and names its function, so a learner can diff it against sp-26's
  // bare label and select sp-26's key with no rule and regardless of how they answered sp-27. The reverse
  // direction is transfer-only. The dependency is NOT removed by this entry — it is prevented from being
  // exercised, exactly as for rb-14/rb-15. Do not read this group as "the items no longer transfer".
  ["sp-26", "sp-27"],
];

/**
 * Same-session mutual exclusion. Given a candidate POOL, keep at most one member of each exclusive
 * group. Applied to the pool (never to the finished result) because the overdraw branch seeds the
 * result with the ENTIRE shuffled pool — a result-level filter would either be bypassed or would
 * silently shorten the session.
 *
 * `groups` and `choose` are injectable so the smoke suite can drive this with a synthetic pool. That
 * injection was ESSENTIAL while both pair members were still held (the live pool could not contain
 * both, so every real-pool assertion was vacuous and a deleted control looked identical to a passing
 * one), and it is retained now that both are released: it still lets a test construct any pool shape
 * on demand rather than depending on what the current hold list happens to allow.
 *
 * The keeper is chosen at random, never fixed: pinning one member would quietly retire the other.
 */
export function collapseExclusiveGroups(
  pool: DrillQuestion[],
  groups: ReadonlyArray<ReadonlyArray<string>> = DEBATE_DRILL_EXCLUSIVE_GROUPS,
  choose: (members: DrillQuestion[]) => DrillQuestion = (members) => members[Math.floor(Math.random() * members.length)]
): DrillQuestion[] {
  let result = pool;
  for (const group of groups) {
    const members = result.filter((q) => group.includes(q.id));
    if (members.length <= 1) continue;
    const keeper = choose(members);
    result = result.filter((q) => !group.includes(q.id) || q.id === keeper.id);
  }
  return result;
}

/**
 * RETAINED-EXPOSURE SIBLING EXCLUSION. Given the bank ids this learner has already been ISSUED
 * (retained history — issuance, not answering: reading a sibling's choices is enough to contaminate),
 * return the ids that must not be freshly served.
 *
 * One member seen -> its siblings are excluded. BOTH members seen -> the whole group is excluded,
 * because there is no uncontaminated measurement left to take while that history remains.
 *
 * TRUTHFULLY BOUNDED, and this is not "once-ever": practice-session rows are purged after
 * COMPLETED_RETENTION_DAYS, so the protection lasts exactly as long as the history does. The purpose
 * is to stop the PLATFORM from handing a learner the decisive logic immediately before measuring the
 * sibling — not to erase long-term memory or blacklist an item forever.
 *
 * NOTE for release: rb-15 entered the bank on 2026-08-11 and the pair was only held on 2026-08-25, so
 * real retained exposure from pre-policy Production sessions may already exist. After any future
 * release some learners will therefore legitimately receive NEITHER sibling until their history ages
 * out. That is the control working as designed — it is not a serving bug.
 */
export function siblingExclusionsFor(
  exposedIds: ReadonlyArray<string>,
  groups: ReadonlyArray<ReadonlyArray<string>> = DEBATE_DRILL_EXCLUSIVE_GROUPS
): string[] {
  const exposed = new Set(exposedIds);
  const excluded = new Set<string>();
  for (const group of groups) {
    const seen = group.filter((id) => exposed.has(id));
    if (seen.length === 0) continue;
    if (seen.length >= 2) {
      for (const id of group) excluded.add(id);
      continue;
    }
    for (const id of group) if (id !== seen[0]) excluded.add(id);
  }
  return [...excluded];
}

/**
 * The real construction logic, with the bank, the hold list and the exclusive groups all INJECTABLE.
 *
 * This exists because of a measured test-design failure found while rb-14 and rb-15 were still held:
 * the live pool could not then contain both, so every assertion made against the real pool was
 * vacuous and a mis-wired control was indistinguishable from a correct one. A mutation audit proved four distinct
 * mis-wirings survived the entire safe battery — enforcement moved after the overdraw seed, applied
 * only when `areas` is defined, applied only when it is undefined, and undone by count pressure.
 * Driving THIS function with a test-only hold list that releases the pair makes all four fail.
 *
 * Production callers must use buildDrillSession below; this is the seam the smoke suite drives.
 */
export function buildDrillSessionFrom(
  bank: DrillQuestion[],
  heldIds: ReadonlyArray<string>,
  count: number,
  areas?: DrillArea[],
  excludedIds?: ReadonlyArray<string>,
  groups: ReadonlyArray<ReadonlyArray<string>> = DEBATE_DRILL_EXCLUSIVE_GROUPS
): DrillQuestion[] {
  const served = bank.filter((q) => !heldIds.includes(q.id));
  const areaPool = areas && areas.length > 0 ? served.filter((q) => areas.includes(q.area)) : served;
  // Retained-exposure exclusions arrive already derived from the issuing route; the builder stays a
  // pure function of (bank, holds, areas, excludedIds) and never touches the database itself.
  const eligible = excludedIds && excludedIds.length > 0 ? areaPool.filter((q) => !excludedIds.includes(q.id)) : areaPool;
  // POOL-LEVEL, unconditionally — never result-level, never conditional on `areas`, and never undone
  // by requested-count pressure. The overdraw branch below seeds the result with the ENTIRE shuffled
  // pool, so a result-level filter would silently shorten sessions instead of protecting them.
  const pool = collapseExclusiveGroups(eligible, groups);
  // An empty pool can never satisfy count >= 1 and the padding loop below would spin forever,
  // synchronously, inside the serving route. An unrecognised area string, a hold that empties an
  // area, or exclusions that remove every candidate must fail loudly here — never hang the server or
  // persist a zero-item active session. (Guard ported from claude/confident-goodall-83f4a0, whose
  // wider diff is NOT taken: that branch predates the amended B1 and carries unrelated item edits.)
  if (pool.length === 0) {
    throw new Error(`Drill pool is empty for areas [${areas?.join(", ") ?? ""}] — cannot build a session`);
  }
  const shuffled = shuffle(pool);
  if (count <= shuffled.length) return shuffled.slice(0, count);
  const result = [...shuffled];
  while (result.length < count) result.push(...shuffle(pool));
  return result.slice(0, count);
}

export function buildDrillSession(count: number, areas?: DrillArea[], excludedIds?: ReadonlyArray<string>): DrillQuestion[] {
  return buildDrillSessionFrom(DRILL_BANK, DEBATE_DRILL_HELD_IDS, count, areas, excludedIds);
}

export type DrillAnswer = { id: string; selected: string };

export type DrillGradedItem = { id: string; area: DrillArea; correct: boolean; correctAnswer: string; explanation: string };

export type DrillSkillResult = { area: DrillArea; skillSlug: string; label: string; total: number; correct: number; scorePercent: number; passed: boolean };

export type DrillResult = {
  total: number;
  correctCount: number;
  scorePercent: number;
  items: DrillGradedItem[];
  perSkill: DrillSkillResult[]; // one entry per area/skill present in the session
};

export const DRILL_PASS_THRESHOLD = 70;

// Server-authoritative grading from the bank, broken down per skill so each skill's mastery and
// spaced review update independently.
export function gradeDrillAnswers(answers: DrillAnswer[]): DrillResult {
  const byId = new Map(DRILL_BANK.map((q) => [q.id, q]));
  const items: DrillGradedItem[] = [];
  const areaTally = new Map<DrillArea, { total: number; correct: number }>();

  for (const answer of answers) {
    const q = byId.get(answer.id);
    if (!q) continue;
    const correct = answer.selected === q.correctAnswer;
    items.push({ id: q.id, area: q.area, correct, correctAnswer: q.correctAnswer, explanation: q.explanation });
    const tally = areaTally.get(q.area) ?? { total: 0, correct: 0 };
    tally.total += 1;
    if (correct) tally.correct += 1;
    areaTally.set(q.area, tally);
  }

  const total = items.length;
  const correctCount = items.filter((i) => i.correct).length;
  const scorePercent = total > 0 ? Math.round((correctCount / total) * 100) : 0;
  const perSkill: DrillSkillResult[] = Array.from(areaTally.entries()).map(([area, tally]) => {
    const meta = DRILL_AREAS.find((a) => a.id === area);
    const pct = tally.total > 0 ? Math.round((tally.correct / tally.total) * 100) : 0;
    return {
      area,
      skillSlug: meta?.skillSlug ?? "",
      label: meta?.label ?? area,
      total: tally.total,
      correct: tally.correct,
      scorePercent: pct,
      passed: pct >= DRILL_PASS_THRESHOLD
    };
  });

  return { total, correctCount, scorePercent, items, perSkill };
}

// --- Duplicate-resistant mastery evidence (M13E1E) ------------------------------------------------
//
// `gradeDrillAnswers` above reports the LEARNER'S SESSION: every graded answer, counted every time it
// was submitted. That is the right number to show someone who just finished a drill, and it is the
// wrong number to persist. Three separate paths turned it into fabricated mastery, all of them live:
//
//   ONE QUESTION.        A single correct answer is 1/1 = 100%, and `masteryLevelFor(100)` is
//                        MASTERED. All four Debate skills are seeded, so that row is written and a
//                        coach can see it. Nothing about answering one multiple-choice question
//                        establishes mastery of rebuttal.
//
//   DUPLICATE INFLATION. Five distinct questions with ONE genuinely correct, plus twelve repeats of
//                        that correct id, tallies 13/17 = 76% — over the 70% threshold. Identical to
//                        the DECA bypass closed in M13E1D.
//
//   HONEST PADDING.      This one needs no bad intent at all. `buildDrillSession` repeats items once
//                        the requested count exceeds an area's nine-question pool, and the UI offers
//                        12 and 20. Every repeat arrives AFTER the learner has already been shown the
//                        correct answer and explanation, so a learner who genuinely knew 6 of 9
//                        reached 85% — MASTERED — by answering the same questions again. The product
//                        manufactured the false mastery itself.
//
// So persistence reads from an EVIDENCE SET instead: at most one entry per valid question id, using
// the FIRST answer submitted for that id.
//
//   first occurrence, not last  — a later answer to an already-answered id is ignored, so seeing the
//                                 explanation and re-answering cannot convert a miss into credit.
//                                 This is exactly what makes the padding path safe.
//   first occurrence, not all   — repeats are legitimate above the nine-item pool, so requiring every
//                                 occurrence to be correct would punish honest practice.
//   ignore, do not reject       — an unrecognised id contributes nothing rather than failing the whole
//                                 submission, and each id is attributed to its OWN bank area.
//
// This makes the evidence duplicate-resistant and unknown-id-resistant. It is NOT tamper-proof: the
// session route still returns `correctAnswer` to the browser and nothing binds a submission to the
// question set the server served. Session binding is deliberately out of scope here (M13E2).
//
// Deliberately Debate-specific. The DECA equivalent in `lib/deca-drills.ts` is not imported and not
// modified: one shared cross-track abstraction would couple two banks that must stay isolated, and
// this slice is not the place to build it.

/**
 * Distinct valid questions required for ONE Debate skill before any progress may be written.
 *
 * Five, matching DECA: each area's bank holds nine distinct items (so five is a majority of what
 * exists), five is the smallest focused-session size the UI offers, and at five questions the 70%
 * threshold needs at least four correct — unreachable on a single lucky answer.
 */
export const DEBATE_DRILL_REQUIRED_UNIQUE = 5;

export type DrillEvidenceStatus = "insufficient-evidence" | "below-threshold" | "passing";

export type DrillSkillEvidence = {
  area: DrillArea;
  skillSlug: string;
  label: string;
  /** Distinct valid question ids submitted for this skill. */
  uniqueTotal: number;
  /** How many of those were correct ON THEIR FIRST submitted answer. */
  uniqueCorrect: number;
  requiredUnique: number;
  /** `uniqueCorrect / uniqueTotal` — the only score that may reach the database. */
  evidenceScore: number;
  evidenceStatus: DrillEvidenceStatus;
  /** True only with enough distinct questions AND an evidence score at or above the threshold. */
  passed: boolean;
};

/** Build the per-skill evidence set for a Debate submission. Pure; deterministic; order-independent. */
export function buildDrillEvidence(answers: DrillAnswer[]): DrillSkillEvidence[] {
  const byId = new Map(DRILL_BANK.map((q) => [q.id, q]));

  // First occurrence per valid id wins; unknown ids and every repeat are dropped here.
  const firstById = new Map<string, { question: DrillQuestion; selected: string }>();
  for (const answer of answers) {
    const question = byId.get(answer.id);
    if (!question) continue;
    if (firstById.has(answer.id)) continue;
    firstById.set(answer.id, { question, selected: answer.selected });
  }

  const tally = new Map<DrillArea, { uniqueTotal: number; uniqueCorrect: number }>();
  for (const { question, selected } of firstById.values()) {
    // Attribution is by the question's OWN area, never by whatever area the session requested.
    const bucket = tally.get(question.area) ?? { uniqueTotal: 0, uniqueCorrect: 0 };
    bucket.uniqueTotal += 1;
    if (selected === question.correctAnswer) bucket.uniqueCorrect += 1;
    tally.set(question.area, bucket);
  }

  return Array.from(tally.entries()).map(([area, bucket]) => {
    const meta = DRILL_AREAS.find((a) => a.id === area);
    const evidenceScore = bucket.uniqueTotal > 0 ? Math.round((bucket.uniqueCorrect / bucket.uniqueTotal) * 100) : 0;
    const evidenceStatus: DrillEvidenceStatus =
      bucket.uniqueTotal < DEBATE_DRILL_REQUIRED_UNIQUE
        ? "insufficient-evidence"
        : evidenceScore >= DRILL_PASS_THRESHOLD
          ? "passing"
          : "below-threshold";
    return {
      area,
      skillSlug: meta?.skillSlug ?? "",
      label: meta?.label ?? area,
      uniqueTotal: bucket.uniqueTotal,
      uniqueCorrect: bucket.uniqueCorrect,
      requiredUnique: DEBATE_DRILL_REQUIRED_UNIQUE,
      evidenceScore,
      evidenceStatus,
      passed: evidenceStatus === "passing"
    };
  });
}

/**
 * What to persist for one Debate skill, or `null` meaning DO NOT CALL the persistence helper.
 *
 * `null` is not "write a zero" — it is the absence of a call, so a short submission cannot write
 * progress, cannot touch the review schedule, and cannot knock an existing mastery down through a
 * due review it never earned the right to answer.
 */
export function debateDrillPersistenceRequest(evidence: DrillSkillEvidence): { scorePercent: number; passed: boolean } | null {
  if (evidence.uniqueTotal < evidence.requiredUnique) return null;
  return { scorePercent: evidence.evidenceScore, passed: evidence.passed };
}
